// src/data/indiaOutline.js
// Pre-simplified India silhouette (mainland + major islands with area > 0.005
// sq-deg, i.e. Andaman & Nicobar / Lakshadweep visible, tiny islets dropped)
// -- generated via Douglas-Peucker from public/india-boundary.geojson
// (mainland epsilon 0.045, island epsilon 0.008, both in degrees). Regenerate
// only if india-boundary.geojson itself changes; this is a build-time asset,
// not derived at render time.
//
// Coordinate space: an equirectangular projection (x = lng, y = -lat, both
// linearly scaled) into a fixed viewBox -- projectToOutline() below maps any
// site's lat/lng into that same space so pins align with the silhouette.

export const OUTLINE_VIEWBOX = { width: 300, height: 311.28 };

const BOUNDS = {
  minLng: 67.87202758800005, maxLng: 97.69498078700006,
  minLat: 6.4529168140000595, maxLat: 37.397589999999994,
};

export function projectToOutline(lat, lng) {
  const x = ((lng - BOUNDS.minLng) / (BOUNDS.maxLng - BOUNDS.minLng)) * OUTLINE_VIEWBOX.width;
  const y = ((BOUNDS.maxLat - lat) / (BOUNDS.maxLat - BOUNDS.minLat)) * OUTLINE_VIEWBOX.height;
  return { x, y };
}

